const AEPortal={
  token:sessionStorage.getItem('ae_portal_token')||'',
  role:sessionStorage.getItem('ae_portal_role')||'',
  account:JSON.parse(sessionStorage.getItem('ae_portal_account')||'null'),
  geoWatch:null,
  lastGeoSent:0,
  liveTimer:null,
};
function portalEsc(v){return String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;')}
function portalText(en,fa){return typeof lang!=='undefined'&&lang==='fa'?fa:en}
function portalMoney(v){return `؋ ${Number(v||0).toLocaleString()}`}
function portalBase(){return(window.AFGHAN_EATS_CONFIG||{}).apiBaseUrl||''}
function portalError(raw,status){try{const j=JSON.parse(raw);return j?.error?.json?.message||j?.error?.message||`Request failed (${status})`}catch{return raw||`Request failed (${status})`}}
async function portalQuery(path,input,auth=true){const b=portalBase();if(!b)throw new Error('API is not configured');const q=encodeURIComponent(JSON.stringify({json:input??null})),h={Accept:'application/json'};if(auth&&AEPortal.token)h.Authorization=`Bearer ${AEPortal.token}`;const r=await fetch(`${b}/api/trpc/${path}?input=${q}`,{headers:h}),raw=await r.text();if(!r.ok)throw new Error(portalError(raw,r.status));const j=JSON.parse(raw);return j?.result?.data?.json??j?.result?.data??j}
async function portalMutation(path,input,auth=true){const b=portalBase();if(!b)throw new Error('API is not configured');const h={'Content-Type':'application/json',Accept:'application/json'};if(auth&&AEPortal.token)h.Authorization=`Bearer ${AEPortal.token}`;const r=await fetch(`${b}/api/trpc/${path}`,{method:'POST',headers:h,body:JSON.stringify({json:input})}),raw=await r.text();if(!r.ok)throw new Error(portalError(raw,r.status));const j=JSON.parse(raw);return j?.result?.data?.json??j?.result?.data??j}
function portalSaveSession(data,role){AEPortal.token=data.token;AEPortal.role=role;AEPortal.account=data.account;sessionStorage.setItem('ae_portal_token',data.token);sessionStorage.setItem('ae_portal_role',role);sessionStorage.setItem('ae_portal_account',JSON.stringify(data.account))}
function portalLogout(){if(AEPortal.geoWatch!=null&&navigator.geolocation)navigator.geolocation.clearWatch(AEPortal.geoWatch);if(AEPortal.liveTimer)clearInterval(AEPortal.liveTimer);sessionStorage.removeItem('ae_portal_token');sessionStorage.removeItem('ae_portal_role');sessionStorage.removeItem('ae_portal_account');AEPortal.token='';AEPortal.role='';AEPortal.account=null;location.reload()}
function portalSetBusy(form,busy,label){const b=form?.querySelector('button[type=submit]');if(!b)return;if(!b.dataset.original)b.dataset.original=b.textContent;b.disabled=busy;b.textContent=busy?(label||'Working…'):b.dataset.original}

window.activatePortal=async function(event){event.preventDefault();const f=event.currentTarget,out=document.getElementById('activateResult'),formData=new FormData(f),token=(String(formData.get('token')||'')||sessionStorage.getItem('ae_portal_activation_token')||'').trim(),password=String(formData.get('password')||''),confirm=String(formData.get('confirm')||'');if(!/^[a-f0-9]{64}$/i.test(token)){out.className='notice error';out.textContent=portalText('This activation link is incomplete, invalid or expired. Please use the full invitation link or ask Afghan Eats for a new one.','این لینک فعال‌سازی ناقص، نامعتبر یا منقضی شده است. لطفاً از لینک کامل دعوت‌نامه استفاده کنید یا از افغان ایتس لینک جدید بخواهید.');return}if(password!==confirm){out.className='notice error';out.textContent=portalText('Passwords do not match.','رمزهای عبور مطابقت ندارند.');return}portalSetBusy(f,true,portalText('Activating…','در حال فعال‌سازی…'));try{const data=await portalMutation('portal.activate',{token,password},false);sessionStorage.removeItem('ae_portal_activation_token');out.className='notice success';out.innerHTML=`✓ ${portalText('Account activated. Your login username is','حساب فعال شد. نام کاربری شما')}: <b>${portalEsc(data.username)}</b>`;setTimeout(()=>location.href=data.role==='owner'?`/owner.html?username=${encodeURIComponent(data.username)}`:`/rider-portal.html?username=${encodeURIComponent(data.username)}`,1200)}catch(e){console.error('Portal activation failed',e);out.className='notice error';out.textContent=portalText('The activation link is invalid, expired, or has already been used. Please ask Afghan Eats operations for a new invitation.','لینک فعال‌سازی نامعتبر، منقضی یا قبلاً استفاده شده است. لطفاً از بخش عملیاتی افغان ایتس دعوت‌نامه جدید بخواهید.')}finally{portalSetBusy(f,false)}}

window.portalLogin=async function(event,role){event.preventDefault();const f=event.currentTarget,out=f.querySelector('.portal-login-error'),d=new FormData(f),username=String(d.get('username')||'').trim();portalSetBusy(f,true,portalText('Signing in…','در حال ورود…'));try{const data=await portalMutation('portal.login',{role,username,password:String(d.get('password')||'')},false);portalSaveSession(data,role);if(out)out.classList.add('hidden');role==='owner'?showOwnerDashboard():showRiderDashboard()}catch(e){const raw=String(e?.message||''),rateLimited=/429|too many|rate.?limit/i.test(raw),invalid=/invalid username or password/i.test(raw),message=rateLimited?portalText('Too many sign-in attempts. Please wait before trying again, or use secure account recovery below.','تلاش‌های ورود بیش از حد بوده است. کمی صبر کنید یا از بازیابی امن حساب در پایین استفاده کنید.'):invalid?portalText('The username or password is incorrect. If you do not remember the password, use secure account recovery.','نام کاربری یا رمز نادرست است. اگر رمز را به یاد ندارید، از بازیابی امن حساب استفاده کنید.'):portalText('We could not sign you in right now. Please try again or use account recovery.','فعلاً ورود انجام نشد. دوباره تلاش کنید یا از بازیابی حساب استفاده کنید.');if(out){out.className='notice error portal-login-error';out.textContent=message}if(role==='owner'&&rateLimited){const input=document.querySelector('#ownerAuth input[name=username]');if(input&&username)input.value=username}}finally{portalSetBusy(f,false)}}
window.openPortalRecovery=function(role){if(role!=='owner')return;const primary=document.getElementById('ownerLoginPrimary'),panel=document.getElementById('ownerRecoveryPanel'),loginUser=document.querySelector('#ownerAuth input[name=username]'),phone=panel?.querySelector('input[name=phone]');if(phone&&!phone.value)phone.value=loginUser?.value?.trim()||'';primary?.classList.add('hidden');panel?.classList.remove('hidden');phone?.focus()}
window.closePortalRecovery=function(role){if(role!=='owner')return;document.getElementById('ownerRecoveryPanel')?.classList.add('hidden');document.getElementById('ownerLoginPrimary')?.classList.remove('hidden')}
window.requestPortalRecovery=async function(event,role){event.preventDefault();const f=event.currentTarget,out=document.getElementById('ownerRecoveryResult'),d=new FormData(f),phone=String(d.get('phone')||'').trim(),restaurantName=String(d.get('restaurantName')||'').trim(),supportNote=String(d.get('supportNote')||'').trim();if(phone.length<9){out.className='notice error';out.textContent=portalText('Enter the phone number used for the portal.','شماره تماسی را که برای پورتال استفاده شده وارد کنید.');return}portalSetBusy(f,true,portalText('Sending request…','در حال ارسال درخواست…'));try{await portalMutation('portal.requestAssistedRecovery',{accountType:role,phone,restaurantName:restaurantName||undefined,supportNote:supportNote||undefined},false);out.className='notice success';out.innerHTML=`<b>${portalEsc(portalText('Recovery request received','درخواست بازیابی دریافت شد'))}</b><br>${portalEsc(portalText('For security, Afghan Eats must verify the request before issuing a private one-time reset link. You do not need to keep trying the old password.','برای امنیت، افغان ایتس باید درخواست را بررسی کند و سپس لینک خصوصی یک‌بارمصرف صادر شود. دیگر لازم نیست رمز قبلی را دوباره امتحان کنید.'))}`;f.querySelectorAll('input,textarea').forEach(el=>el.disabled=true);f.querySelector('button[type=submit]').classList.add('hidden')}catch(e){const raw=String(e?.message||''),rateLimited=/429|too many|rate.?limit/i.test(raw);out.className='notice error';out.textContent=rateLimited?portalText('Too many requests were sent recently. Please wait a few minutes and submit the recovery request again.','در مدت کوتاه درخواست‌های زیادی ارسال شده است. چند دقیقه صبر کنید و دوباره درخواست بازیابی را ارسال نمایید.'):portalText('We could not submit the recovery request right now. Please try again shortly.','فعلاً درخواست بازیابی ارسال نشد. لطفاً کمی بعد دوباره تلاش کنید.')}finally{portalSetBusy(f,false)}}
async function portalVerify(role){if(!AEPortal.token||AEPortal.role!==role)return false;try{const me=await portalQuery('portal.me',null,true);if(me.role!==role)throw new Error('Wrong portal role');AEPortal.account=me;return true}catch{portalLogout();return false}}

const AEOwner={restaurant:null,categories:[],items:[],history:[]};
const ownerDays=[['monday','Monday','دوشنبه'],['tuesday','Tuesday','سه‌شنبه'],['wednesday','Wednesday','چهارشنبه'],['thursday','Thursday','پنج‌شنبه'],['friday','Friday','جمعه'],['saturday','Saturday','شنبه'],['sunday','Sunday','یک‌شنبه']];
function ownerFormControl(form,name){return form?.elements?.namedItem(name)||null}
function ownerStatusActions(o){const map={placed:['confirmed','cancelled'],confirmed:['preparing','cancelled'],preparing:['ready_for_pickup','cancelled']},next=map[o.status]||[];return next.map(s=>`<button class="btn ${s==='cancelled'?'btn-light':'btn-primary'} btn-sm" onclick="ownerOrderStatus('${portalEsc(o.id)}','${s}')">${portalEsc(s.replaceAll('_',' '))}</button>`).join('')}
function portalItems(items){const a=Array.isArray(items)?items:[];return a.map(i=>`${portalEsc(i.quantity||1)}× ${portalEsc(i.name||i.name_dari||'Item')}`).join(' · ')}
function ownerNotice(message,error=false){const el=document.getElementById('ownerToast');if(!el)return;el.className=`notice ${error?'error':'success'}`;el.textContent=message;el.scrollIntoView({behavior:'smooth',block:'nearest'});clearTimeout(ownerNotice.timer);ownerNotice.timer=setTimeout(()=>el.classList.add('hidden'),5000)}
window.showOwnerPanel=function(id,button){document.querySelectorAll('.owner-panel').forEach(panel=>panel.classList.toggle('hidden',panel.id!==id));document.querySelectorAll('.owner-tab').forEach(tab=>tab.classList.toggle('active',tab===button));if(button)button.setAttribute('aria-current','page');document.querySelectorAll('.owner-tab').forEach(tab=>{if(tab!==button)tab.removeAttribute('aria-current')});if(window.innerWidth<901)document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'})};window.ownerGoPanel=function(id){const button=document.querySelector(`.owner-tab[data-owner-panel="${id}"]`);window.showOwnerPanel(id,button)}
window.ownerGoSetupStep=function(key){const menu=key==='menu',panel=menu?'ownerMenuPanel':'ownerStorePanel';window.ownerGoPanel(panel);const targets={profile:'ownerProfileForm',branding:'ownerProfileForm',hours:'ownerHours',fulfilment:'storeDelivery',delivery:'storeMinTime',commerce:'storeMinOrder',menu:'ownerMenuPanel'},id=targets[key];setTimeout(()=>document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'center'}),120)}
window.dismissOwnerWelcome=function(){const id=AEOwner.restaurant?.id;if(id)sessionStorage.setItem(`ae_owner_welcome_${id}`,'1');document.querySelector('.owner-welcome-card')?.classList.add('hidden')}
function showOwnerDashboard(){document.getElementById('ownerAuth')?.classList.add('hidden');document.getElementById('ownerDashboard')?.classList.remove('hidden');loadOwnerDashboard()}
async function loadOwnerDashboard(){
  const err=document.getElementById('ownerError');
  try{
    const[dash,menu,history,setup]=await Promise.all([portalQuery('portal.ownerDashboard'),portalQuery('portal.ownerMenu'),portalQuery('portal.ownerChangeHistory'),portalQuery('portal.ownerSetupSubmission')]);
    if(err)err.classList.add('hidden');
    const r=dash.restaurant||{},stats=dash.stats||{},orders=dash.orders||[];AEOwner.restaurant=r;AEOwner.categories=menu.categories||[];AEOwner.items=menu.items||[];AEOwner.history=history||[];AEOwner.orders=orders;AEOwner.stats=stats;
    const title=document.getElementById('ownerTitle');if(title)title.textContent=portalText(r.name||'Restaurant',r.name_dari||r.name||'رستورانت');
    const publicUrl=`/restaurant.html?id=${encodeURIComponent(r.id||'')}`;['ownerPublicLink','ownerSidePublicLink'].forEach(id=>{const el=document.getElementById(id);if(el)el.href=publicUrl});
    const status=document.getElementById('ownerHeroStatus');if(status){const open=r.status==='active'&&r.is_open;status.className=`owner-status-pill ${open?'is-open':'is-closed'}`;status.textContent=r.status!=='active'?portalText('Onboarding','در حال فعال‌سازی'):open?portalText('Open & accepting','باز و فعال'):portalText('Closed','بسته')}
    const hero=document.getElementById('ownerHeroMedia'),cover=/^https:\/\//i.test(r.cover_image_url||'')?r.cover_image_url:/^https:\/\//i.test(r.logo_url||'')?r.logo_url:'';if(hero){hero.innerHTML=cover?`<img src="${portalEsc(cover)}" alt="">`:`<div class="owner-hero-placeholder">${portalEsc((r.name||'AE').slice(0,2).toUpperCase())}</div>`}
    const activeItems=AEOwner.items.filter(i=>!i.archived_at),availableItems=activeItems.filter(i=>i.is_available!==false),avg=orders.length?orders.reduce((sum,o)=>sum+Number(o.total||0),0)/orders.length:0;
    const kpis=[
      ['▤',portalText('Orders today','سفارش‌های امروز'),stats.orders_today||0],
      ['؋',portalText('Delivered GMV today','فروش تحویل‌شده امروز'),portalMoney(stats.delivered_gmv||0)],
      ['◫',portalText('Average recent order','میانگین سفارش اخیر'),portalMoney(avg)],
      ['☷',portalText('Active menu items','آیتم‌های فعال منو'),availableItems.length],
      ['×',portalText('Cancelled today','لغوشده امروز'),stats.cancelled_today||0],
      ['●',portalText('Store status','وضعیت رستورانت'),r.is_open?portalText('Open','باز'):portalText('Closed','بسته')]
    ];const statsEl=document.getElementById('ownerStats');if(statsEl)statsEl.innerHTML=kpis.map(([icon,label,value],index)=>`<article class="owner-kpi-card kpi-${index}"><span class="owner-kpi-icon">${portalEsc(icon)}</span><small>${portalEsc(label)}</small><strong>${portalEsc(value)}</strong></article>`).join('');
    const orderPreview=document.getElementById('ownerOverviewOrders');if(orderPreview)orderPreview.innerHTML=orders.length?orders.slice(0,5).map(o=>`<button class="owner-activity-row" type="button" onclick="ownerGoPanel('ownerOrdersPanel')"><span class="owner-activity-time">${new Date(o.created_at).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}</span><span class="owner-activity-order"><b>${portalEsc(o.order_number)}</b><small>${portalEsc(portalItems(o.items))}</small></span><span class="status-badge status-${portalEsc(o.status)}">${portalEsc(o.status.replaceAll('_',' '))}</span><strong>${portalMoney(o.total)}</strong></button>`).join(''):`<div class="portal-empty">${portalText('No recent orders yet.','هنوز سفارش اخیری نیست.')}</div>`;
    const values=document.getElementById('ownerRecentValues');if(values){const recent=orders.slice(0,7).reverse(),max=Math.max(1,...recent.map(o=>Number(o.total||0)));values.innerHTML=recent.length?recent.map((o,i)=>`<div class="owner-value-column"><div class="owner-value-track"><span style="height:${Math.max(10,Math.round(Number(o.total||0)/max*100))}%"></span></div><small>${portalMoney(o.total)}</small></div>`).join(''):`<div class="portal-empty">${portalText('Order values will appear here after your first orders.','پس از نخستین سفارش‌ها، ارزش سفارش‌ها اینجا نمایش داده می‌شود.')}</div>`}
    const menuPreview=document.getElementById('ownerOverviewMenu');if(menuPreview)menuPreview.innerHTML=activeItems.length?activeItems.slice(0,4).map(i=>{const img=/^https:\/\//i.test(i.image_url||'')?`<img src="${portalEsc(i.image_url)}" alt="">`:`<div class="owner-preview-placeholder">🍽️</div>`;return`<article class="owner-preview-item">${img}<div><b>${portalEsc(portalText(i.name||'',i.name_dari||i.name||''))}</b><span>${portalMoney(i.price)}</span><small class="${i.is_available!==false?'available':'unavailable'}">${portalEsc(i.is_available!==false?portalText('Available','موجود'):portalText('Unavailable','ناموجود'))}</small></div></article>`}).join(''):`<div class="portal-empty">${portalText('Add menu items to see them here.','برای نمایش در اینجا، آیتم منو اضافه کنید.')}</div>`;
    const snapshot=document.getElementById('ownerBusinessSnapshot');if(snapshot)snapshot.innerHTML=`<div class="owner-business-list"><div><span>☎</span><p><small>${portalText('Phone','شماره تماس')}</small><b dir="ltr">${portalEsc(r.phone||'—')}</b></p></div><div><span>⌖</span><p><small>${portalText('District','ناحیه')}</small><b>${portalEsc(r.district||'—')}</b></p></div><div><span>🛵</span><p><small>${portalText('Delivery','ارسال')}</small><b>${portalEsc(r.has_delivery!==false?portalText('Enabled','فعال'):portalText('Disabled','غیرفعال'))}</b></p></div><div><span>⌂</span><p><small>${portalText('Pickup','دریافت حضوری')}</small><b>${portalEsc(r.has_takeaway!==false?portalText('Enabled','فعال'):portalText('Disabled','غیرفعال'))}</b></p></div><div><span>◷</span><p><small>${portalText('ETA','زمان آماده‌سازی')}</small><b dir="ltr">${portalEsc(`${r.delivery_time_min??25}–${r.delivery_time_max??45} min`)}</b></p></div><div><span>؋</span><p><small>${portalText('Minimum order','حداقل سفارش')}</small><b>${portalMoney(r.min_order_amount||0)}</b></p></div></div>`;
    document.getElementById('ownerOrders').innerHTML=orders.length?orders.map(o=>`<article class="portal-order"><div class="portal-order-head"><div><b>${portalEsc(o.order_number)}</b><div class="portal-meta"><span>${new Date(o.created_at).toLocaleString()}</span><span dir="ltr">${portalEsc(o.delivery_phone||'')}</span></div></div><div><b>${portalMoney(o.total)}</b><div class="status-badge status-${portalEsc(o.status)}">${portalEsc(o.status.replaceAll('_',' '))}</div></div></div><div class="owner-order-items">${portalItems(o.items)}</div><div class="delivery-address">📍 ${portalEsc(o.delivery_address||'')}</div><div class="portal-actions">${ownerStatusActions(o)}</div></article>`).join(''):`<div class="portal-empty">${portalText('No orders yet.','هنوز سفارشی نیست.')}</div>`;
    const activation=document.getElementById('ownerActivationNotice');
    if(r.status!=='active'){activation.className='notice';activation.innerHTML=`<div class="owner-status-note"><div><b>${portalEsc(portalText('Your restaurant is still in onboarding','رستورانت شما هنوز در مرحله فعال‌سازی است'))}</b><span>${portalEsc(portalText('You can prepare the menu and profile now. Afghan Eats operations must activate ordering after verification.','اکنون می‌توانید منو و پروفایل را آماده کنید. فعال‌سازی سفارش پس از بررسی توسط تیم افغان ایتس انجام می‌شود.'))}</span></div><span class="status-badge status-${portalEsc(r.status||'pending')}">${portalEsc(r.status||'pending')}</span></div>`}else activation.classList.add('hidden');
    document.getElementById('storeOpen').checked=!!r.is_open;document.getElementById('storeDelivery').checked=r.has_delivery!==false;document.getElementById('storePickup').checked=r.has_takeaway!==false;document.getElementById('storeMinTime').value=r.delivery_time_min??25;document.getElementById('storeMaxTime').value=r.delivery_time_max??45;document.getElementById('storeDeliveryFee').value=Number(r.delivery_fee_min||0);document.getElementById('storeMinOrder').value=Number(r.min_order_amount||0);
    renderOwnerOnboarding(setup);renderOwnerSetupReview(setup);renderOwnerMenu();renderOwnerCategories();renderOwnerProfile();renderOwnerHistory();
  }catch(e){if(err){err.className='notice error';err.textContent=e.message}}
}
function ownerMenuCard(i,archived=false){const image=/^https:\/\//i.test(i.image_url||'')?`<img src="${portalEsc(i.image_url)}" alt="">`:'<div class="owner-menu-thumb" aria-hidden="true">🍽️</div>',flags=[i.is_available?portalText('Available','موجود'):portalText('Unavailable','ناموجود'),i.is_popular?portalText('Popular','محبوب'):'',i.is_vegetarian?portalText('Vegetarian','گیاهی'):'',i.is_spicy?portalText('Spicy','تند'):''].filter(Boolean);return`<article class="portal-menu-item owner-menu-card">${image}<div class="owner-menu-copy"><h3>${portalEsc(i.name)}</h3>${i.name_dari?`<div dir="rtl">${portalEsc(i.name_dari)}</div>`:''}<p>${portalEsc(portalText(i.description||'',i.description_dari||i.description||''))}</p><div class="owner-menu-price">${portalMoney(i.price)}</div><div class="owner-menu-flags">${flags.map(f=>`<span>${portalEsc(f)}</span>`).join('')}</div></div><div class="owner-menu-actions">${archived?`<button class="btn btn-light btn-sm" type="button" onclick="restoreOwnerItem('${portalEsc(i.id)}')">${portalText('Restore','برگرداندن')}</button>`:`<button class="btn btn-light btn-sm" type="button" onclick="editOwnerItem('${portalEsc(i.id)}')">${portalText('Edit','ویرایش')}</button><button class="btn btn-light btn-sm" type="button" onclick="archiveOwnerItem('${portalEsc(i.id)}')">${portalText('Archive','آرشیف')}</button>`}</div></article>`}
function renderOwnerMenu(){const active=AEOwner.items.filter(i=>!i.archived_at),archived=AEOwner.items.filter(i=>i.archived_at),list=document.getElementById('ownerMenu'),archive=document.getElementById('ownerArchivedMenu');if(list)list.innerHTML=active.length?active.map(i=>ownerMenuCard(i)).join(''):`<div class="portal-empty">${portalText('No menu items yet. Add the first dish using the form.','هنوز آیتمی در منو نیست. نخستین غذا را با فورم اضافه کنید.')}</div>`;if(archive)archive.innerHTML=archived.length?archived.map(i=>ownerMenuCard(i,true)).join(''):`<div class="portal-empty">${portalText('No archived items.','آیتم آرشیف‌شده‌ای نیست.')}</div>`;const select=document.getElementById('ownerItemCategory');if(select){const current=select.value;select.innerHTML=`<option value="">${portalText('Uncategorized','بدون دسته‌بندی')}</option>`+AEOwner.categories.map(c=>`<option value="${portalEsc(c.id)}">${portalEsc(portalText(c.name,c.name_dari||c.name))}</option>`).join('');select.value=current}}
window.startNewOwnerItem=function(){const panel=document.getElementById('ownerMenuPanel'),tab=document.querySelector('.owner-tab[data-owner-panel="ownerMenuPanel"]'),f=document.getElementById('ownerItemForm');if(!f)return;document.querySelectorAll('.owner-panel').forEach(item=>item.classList.toggle('hidden',item!==panel));document.querySelectorAll('.owner-tab').forEach(item=>item.classList.toggle('active',item===tab));f.reset();const id=ownerFormControl(f,'id'),sortOrder=ownerFormControl(f,'sortOrder'),isAvailable=ownerFormControl(f,'isAvailable');if(id)id.value='';if(sortOrder)sortOrder.value='0';if(isAvailable)isAvailable.checked=true;document.getElementById('ownerItemFormTitle').textContent=portalText('Add menu item','افزودن آیتم منو');setTimeout(()=>{f.scrollIntoView({behavior:'smooth',block:'start'});ownerFormControl(f,'name')?.focus({preventScroll:true})},0)}
window.editOwnerItem=function(id){const i=AEOwner.items.find(item=>String(item.id)===String(id)),f=document.getElementById('ownerItemForm');if(!i||!f)return;for(const [name,value] of Object.entries({id:i.id,categoryId:i.category_id||'',name:i.name||'',nameDari:i.name_dari||'',description:i.description||'',descriptionDari:i.description_dari||'',price:Number(i.price||0),imageUrl:i.image_url||'',sortOrder:Number(i.sort_order||0)})){const control=ownerFormControl(f,name);if(control)control.value=value}for(const name of ['isAvailable','isPopular','isVegetarian','isSpicy']){const control=ownerFormControl(f,name);if(control)control.checked=!!i[name.replace(/[A-Z]/g,m=>'_'+m.toLowerCase())]}document.getElementById('ownerItemFormTitle').textContent=portalText('Edit menu item','ویرایش آیتم منو');f.scrollIntoView({behavior:'smooth',block:'start'})}
window.saveOwnerMenuItem=async function(event){event.preventDefault();const f=event.currentTarget,d=new FormData(f),payload={categoryId:String(d.get('categoryId')||'')||null,name:String(d.get('name')||''),nameDari:String(d.get('nameDari')||''),description:String(d.get('description')||''),descriptionDari:String(d.get('descriptionDari')||''),price:Number(d.get('price')||0),imageUrl:String(d.get('imageUrl')||''),isAvailable:d.get('isAvailable')==='on',isPopular:d.get('isPopular')==='on',isVegetarian:d.get('isVegetarian')==='on',isSpicy:d.get('isSpicy')==='on',sortOrder:Number(d.get('sortOrder')||0)},id=String(d.get('id')||'');if(id)payload.id=id;portalSetBusy(f,true,portalText('Saving…','در حال ذخیره…'));try{await portalMutation('portal.ownerUpsertMenuItem',payload);ownerNotice(portalText('Menu item saved.','آیتم منو ذخیره شد.'));startNewOwnerItem();await loadOwnerDashboard()}catch(e){ownerNotice(e.message,true)}finally{portalSetBusy(f,false)}}
window.archiveOwnerItem=async function(id){if(!confirm(portalText('Archive this item? It will disappear from the public menu but can be restored.','این آیتم آرشیف شود؟ از منوی عمومی پنهان می‌شود اما قابل بازگرداندن است.')))return;try{await portalMutation('portal.ownerArchiveMenuItem',{id});ownerNotice(portalText('Item archived.','آیتم آرشیف شد.'));await loadOwnerDashboard()}catch(e){ownerNotice(e.message,true)}}
window.restoreOwnerItem=async function(id){try{await portalMutation('portal.ownerRestoreMenuItem',{id});ownerNotice(portalText('Item restored.','آیتم بازگردانده شد.'));await loadOwnerDashboard()}catch(e){ownerNotice(e.message,true)}}
function renderOwnerCategories(){const el=document.getElementById('ownerCategories');if(!el)return;el.innerHTML=AEOwner.categories.length?AEOwner.categories.map(c=>`<div class="owner-category-row"><div><b>${portalEsc(c.name)}</b>${c.name_dari?`<div dir="rtl">${portalEsc(c.name_dari)}</div>`:''}</div><button class="btn btn-light btn-sm" type="button" onclick="editOwnerCategory('${portalEsc(c.id)}')">${portalText('Edit','ویرایش')}</button></div>`).join(''):`<div class="portal-empty">${portalText('No categories yet.','هنوز دسته‌بندی نیست.')}</div>`}
window.editOwnerCategory=function(id){const c=AEOwner.categories.find(category=>String(category.id)===String(id)),f=document.getElementById('ownerCategoryForm');if(!c||!f)return;for(const [name,value] of Object.entries({id:c.id,name:c.name||'',nameDari:c.name_dari||'',sortOrder:Number(c.sort_order||0)})){const control=ownerFormControl(f,name);if(control)control.value=value}f.scrollIntoView({behavior:'smooth',block:'center'})}
window.saveOwnerCategory=async function(event){event.preventDefault();const f=event.currentTarget,d=new FormData(f),payload={name:String(d.get('name')||''),nameDari:String(d.get('nameDari')||''),sortOrder:Number(d.get('sortOrder')||0)},id=String(d.get('id')||'');if(id)payload.id=id;portalSetBusy(f,true,portalText('Saving…','در حال ذخیره…'));try{await portalMutation('portal.ownerUpsertMenuCategory',payload);f.reset();const itemId=ownerFormControl(f,'id'),sortOrder=ownerFormControl(f,'sortOrder');if(itemId)itemId.value='';if(sortOrder)sortOrder.value='0';ownerNotice(portalText('Menu category saved.','دسته‌بندی منو ذخیره شد.'));await loadOwnerDashboard()}catch(e){ownerNotice(e.message,true)}finally{portalSetBusy(f,false)}}
function renderOwnerOnboarding(setup){
  const host=document.getElementById('ownerOnboardingGuide'),r=AEOwner.restaurant||{},submission=setup?.submission||null,readiness=setup?.readiness||null;
  if(!host)return;
  if(r.status==='active'){host.classList.add('hidden');host.innerHTML='';return}
  const fallbackSteps=[
    {key:'profile',done:false},{key:'branding',done:false},{key:'hours',done:false},{key:'fulfilment',done:false},{key:'delivery',done:false},{key:'commerce',done:false},{key:'menu',done:false}
  ],steps=Array.isArray(readiness?.steps)?readiness.steps:fallbackSteps,completed=Number(readiness?.completed||steps.filter(s=>s.done).length),total=Number(readiness?.total||steps.length),progress=Number(readiness?.progress??Math.round(completed/Math.max(1,total)*100)),ready=Boolean(readiness?.ready??completed===total);
  const copy={
    profile:['Restaurant profile','پروفایل رستورانت','Name, description, address, district and phone','نام، توضیحات، آدرس، ناحیه و شماره تماس'],
    branding:['Logo & cover','لوگو و تصویر کاور','Add the restaurant logo and a strong cover image','لوگو و تصویر اصلی رستورانت را اضافه کنید'],
    hours:['Opening hours','ساعات کاری','Set opening hours for every day of the week','ساعات کاری همه روزهای هفته را تنظیم کنید'],
    fulfilment:['Delivery or pickup','ارسال یا دریافت حضوری','Enable at least one way customers can receive orders','حداقل یک روش دریافت سفارش را فعال کنید'],
    delivery:['Delivery details','تنظیمات ارسال','Set delivery ETA and fee when delivery is enabled','زمان و هزینه ارسال را در صورت فعال بودن ارسال تعیین کنید'],
    commerce:['Minimum order','حداقل سفارش','Set the minimum order amount for customers','حداقل مبلغ سفارش مشتری را تعیین کنید'],
    menu:['Menu ready','منو آماده','Add at least one available menu item with a price','حداقل یک آیتم موجود با قیمت به منو اضافه کنید']
  };
  const firstVisit=!sessionStorage.getItem(`ae_owner_welcome_${r.id||''}`)&&!submission;
  const welcome=firstVisit?`<article class="owner-welcome-card"><button type="button" class="owner-welcome-close" onclick="dismissOwnerWelcome()" aria-label="Dismiss">×</button><span class="owner-welcome-kicker">${portalEsc(portalText('Welcome to Afghan Eats','به افغان ایتس خوش آمدید'))}</span><h2>${portalEsc(portalText(`Let's get ${r.name||'your restaurant'} ready for customers`,`بیایید ${r.name_dari||r.name||'رستورانت شما'} را برای مشتریان آماده کنیم`))}</h2><p>${portalEsc(portalText('Complete the setup steps below. When everything is ready, submit your restaurant to Afghan Eats for final review and marketplace activation.','مراحل زیر را تکمیل کنید. وقتی همه‌چیز آماده شد، رستورانت را برای بررسی نهایی و فعال‌سازی در بازار افغان ایتس ارسال کنید.'))}</p></article>`:'';
  const state=submission?.status==='submitted'?'review':submission?.status==='changes_requested'?'changes':submission?.status==='approved'?'approved':ready?'ready':'setup';
  const stateCopy={
    setup:[`${Math.max(0,total-completed)} steps left`,`${Math.max(0,total-completed)} مرحله باقی مانده`],
    ready:['Ready to submit','آماده ارسال'],
    review:['Under Afghan Eats review','در حال بررسی افغان ایتس'],
    changes:['Changes requested','درخواست تغییرات'],
    approved:['Setup approved','تنظیمات تأیید شده']
  };
  const stepHtml=steps.map(step=>{const c=copy[step.key]||[step.key,step.key,'',''];const aria=step.key==='menu'?portalText('Open food catalog setup','باز کردن تنظیم فهرست غذاها'):portalText(`Open ${c[0]} setup`,`باز کردن تنظیم ${c[1]}`);return`<button type="button" aria-label="${portalEsc(aria)}" class="owner-setup-step ${step.done?'done':'pending'}" onclick="ownerGoSetupStep('${portalEsc(step.key)}')"><span class="owner-step-check">${step.done?'✓':'○'}</span><span class="owner-step-copy"><b>${portalEsc(portalText(c[0],c[1]))}</b><small>${portalEsc(portalText(c[2],c[3]))}</small></span><span class="owner-step-action">${portalEsc(step.done?portalText('Done','تکمیل'):portalText('Set up','تکمیل'))}</span></button>`}).join('');
  const submitAction=ready&&!submission?`<button class="btn btn-primary owner-ready-submit" type="button" onclick="document.getElementById('ownerSetupReview')?.scrollIntoView({behavior:'smooth',block:'center'})">${portalEsc(portalText('Submit for Afghan Eats review','ارسال برای بررسی افغان ایتس'))}</button>`:'';
  host.innerHTML=`${welcome}<div class="owner-launch-card state-${state}"><div class="owner-launch-summary"><div class="owner-progress-ring" style="--owner-progress:${Math.min(100,Math.max(0,progress))}"><span>${Math.min(100,Math.max(0,progress))}%</span></div><div><span class="owner-card-kicker">${portalEsc(portalText('Launch setup','آمادگی برای شروع'))}</span><h2>${portalEsc(state==='approved'?portalText('Your setup is approved','تنظیمات شما تأیید شده است'):state==='review'?portalText('Your setup is under review','تنظیمات شما در حال بررسی است'):ready?portalText('Your restaurant is ready for review','رستورانت شما آماده بررسی است'):portalText('Complete your restaurant setup','تنظیمات رستورانت را تکمیل کنید'))}</h2><p>${portalEsc(portalText(...stateCopy[state]))}</p>${submitAction}</div></div><div class="owner-setup-steps">${stepHtml}</div></div>`;
  host.classList.remove('hidden');
}
function renderOwnerSetupReview(setup){const el=document.getElementById('ownerSetupReview');if(!el)return;const submission=setup?.submission||null,issues=Array.isArray(setup?.completionIssues)?setup.completionIssues:[];if(submission?.status==='submitted'){el.innerHTML=`<div class="owner-status-note"><div><b>${portalEsc(portalText('Setup submitted for Afghan Eats review','تنظیمات برای بررسی افغان ایتس ارسال شد'))}</b><span>${portalEsc(portalText('Your profile, menu and delivery details are locked while the team reviews this submission.','پروفایل، منو و معلومات ارسال شما تا پایان بررسی قفل است.'))}</span>${submission.owner_note?`<small>${portalEsc(portalText('Your note: ','یادداشت شما: '))}${portalEsc(submission.owner_note)}</small>`:''}</div><span class="status-badge status-pending">${portalEsc(portalText('under review','در حال بررسی'))}</span></div>`;return}if(submission?.status==='changes_requested'){el.innerHTML=`<h2>${portalEsc(portalText('Changes requested','درخواست تغییرات'))}</h2><p>${portalEsc(submission.admin_note||portalText('Afghan Eats has requested changes before approval.','افغان ایتس پیش از تأیید، تغییرات خواسته است.'))}</p>${setupSubmitForm(portalText('Resubmit completed setup','ارسال دوباره تنظیمات'))}`;return}if(submission?.status==='approved'){el.innerHTML=`<div class="owner-status-note"><div><b>${portalEsc(portalText('Setup approved','تنظیمات تأیید شد'))}</b><span>${portalEsc(portalText('Afghan Eats has approved this setup. The team controls the final public listing activation.','افغان ایتس این تنظیمات را تأیید کرده است. فعال‌سازی نهایی فهرست عمومی توسط تیم انجام می‌شود.'))}</span></div><span class="status-badge status-approved">${portalEsc(portalText('approved','تأیید شده'))}</span></div>`;return}const issueCopy=issues.length?`<p class="muted">${portalEsc(portalText('Before submitting, complete: ','پیش از ارسال، تکمیل کنید: '))}${portalEsc(issues.join(', '))}</p>`:`<p class="muted">${portalEsc(portalText('Save your restaurant profile, delivery settings, opening hours, and at least one menu item. Then submit the complete setup for Afghan Eats approval.','پروفایل رستورانت، تنظیمات ارسال، ساعات کاری و دست‌کم یک آیتم منو را ذخیره کنید. سپس تنظیمات کامل را برای تأیید افغان ایتس ارسال کنید.'))}</p>`;el.innerHTML=`<h2>${portalEsc(portalText('Submit restaurant setup for review','ارسال تنظیمات رستورانت برای بررسی'))}</h2>${issueCopy}${setupSubmitForm(portalText('Submit complete setup','ارسال تنظیمات کامل'))}`}
function setupSubmitForm(label){return`<form id="ownerSetupSubmitForm" class="owner-editor-form" onsubmit="submitOwnerSetup(event)"><label class="field"><span>${portalEsc(portalText('Note for Afghan Eats (optional)','یادداشت برای افغان ایتس (اختیاری)'))}</span><textarea name="ownerNote" maxlength="3000" rows="2" placeholder="${portalEsc(portalText('Tell the reviewer anything important about your menu, delivery or availability.','درباره منو، ارسال یا آمادگی رستورانت نکات مهم را بنویسید.'))}"></textarea></label><button class="btn btn-primary" type="submit">${portalEsc(label)}</button></form>`}
window.submitOwnerSetup=async function(event){event.preventDefault();const f=event.currentTarget,d=new FormData(f);if(!confirm(portalText('Submit your complete restaurant setup for Afghan Eats review? You will not be able to edit it until the team responds.','تنظیمات کامل رستورانت برای بررسی افغان ایتس ارسال شود؟ تا پاسخ تیم، امکان ویرایش نخواهید داشت.')))return;portalSetBusy(f,true,portalText('Submitting…','در حال ارسال…'));try{await portalMutation('portal.ownerSubmitSetup',{ownerNote:String(d.get('ownerNote')||'')});ownerNotice(portalText('Setup submitted for Afghan Eats review.','تنظیمات برای بررسی افغان ایتس ارسال شد.'));await loadOwnerDashboard()}catch(e){ownerNotice(e.message,true)}finally{portalSetBusy(f,false)}}
function renderOwnerProfile(){const r=AEOwner.restaurant||{},f=document.getElementById('ownerProfileForm');if(f){for(const [name,value] of Object.entries({name:r.name||'',nameDari:r.name_dari||'',description:r.description||'',descriptionDari:r.description_dari||'',address:r.address||'',addressDari:r.address_dari||'',district:r.district||'',neighborhood:r.neighborhood||'',phone:r.phone||'',logoUrl:r.logo_url||'',coverImageUrl:r.cover_image_url||''})){const control=ownerFormControl(f,name);if(control)control.value=value}}const hours=r.opening_hours&&typeof r.opening_hours==='object'?r.opening_hours:{},el=document.getElementById('ownerHours');if(el)el.innerHTML=ownerDays.map(([key,en,fa])=>{const value=String(hours[key]||'09:00-22:00').toLowerCase(),closed=value==='closed',[open,close]=closed?['09:00','22:00']:value.split('-');return`<div class="owner-hour-row ${closed?'closed':''}" data-day="${key}"><span>${portalEsc(portalText(en,fa))}</span><input class="hour-open" type="time" value="${portalEsc(open||'09:00')}" aria-label="${portalEsc(en)} opening time"><input class="hour-close" type="time" value="${portalEsc(close||'22:00')}" aria-label="${portalEsc(en)} closing time"><label><input class="hour-closed" type="checkbox" ${closed?'checked':''} onchange="this.closest('.owner-hour-row').classList.toggle('closed',this.checked)"> ${portalText('Closed','بسته')}</label></div>`}).join('')}
function ownerHoursPayload(){const out={};document.querySelectorAll('.owner-hour-row').forEach(row=>{out[row.dataset.day]=row.querySelector('.hour-closed').checked?'closed':`${row.querySelector('.hour-open').value}-${row.querySelector('.hour-close').value}`});return out}
window.saveOwnerProfile=async function(event){if(event)event.preventDefault();const f=document.getElementById('ownerProfileForm');if(!f)return;const d=new FormData(f),payload={name:String(d.get('name')||''),nameDari:String(d.get('nameDari')||''),description:String(d.get('description')||''),descriptionDari:String(d.get('descriptionDari')||''),address:String(d.get('address')||''),addressDari:String(d.get('addressDari')||''),district:String(d.get('district')||''),neighborhood:String(d.get('neighborhood')||''),phone:String(d.get('phone')||''),logoUrl:String(d.get('logoUrl')||''),coverImageUrl:String(d.get('coverImageUrl')||''),openingHours:ownerHoursPayload()};if(event)portalSetBusy(f,true,portalText('Saving…','در حال ذخیره…'));try{await portalMutation('portal.ownerUpdateRestaurantContent',payload);ownerNotice(portalText('Restaurant profile and opening hours saved.','پروفایل و ساعات کاری رستورانت ذخیره شد.'));await loadOwnerDashboard()}catch(e){ownerNotice(e.message,true)}finally{if(event)portalSetBusy(f,false)}}
function renderOwnerHistory(){const el=document.getElementById('ownerHistory');if(!el)return;el.innerHTML=AEOwner.history.length?AEOwner.history.slice(0,12).map(item=>`<div class="owner-history-row"><span>${portalEsc(item.action.replaceAll('.',' · '))}</span><time datetime="${portalEsc(item.created_at)}">${new Date(item.created_at).toLocaleString()}</time></div>`).join(''):`<div class="portal-empty">${portalText('No owner changes recorded yet.','هنوز تغییری ثبت نشده است.')}</div>`}
window.ownerOrderStatus=async function(orderId,status){try{await portalMutation('portal.ownerUpdateOrderStatus',{orderId,status});ownerNotice(portalText('Order status updated.','وضعیت سفارش به‌روزرسانی شد.'));await loadOwnerDashboard()}catch(e){ownerNotice(e.message,true)}}
window.saveOwnerStore=async function(){try{await portalMutation('portal.ownerUpdateStore',{isOpen:document.getElementById('storeOpen').checked,hasDelivery:document.getElementById('storeDelivery').checked,hasTakeaway:document.getElementById('storePickup').checked,deliveryTimeMin:Number(document.getElementById('storeMinTime').value||25),deliveryTimeMax:Number(document.getElementById('storeMaxTime').value||45),deliveryFeeMin:Number(document.getElementById('storeDeliveryFee').value||0),minOrderAmount:Number(document.getElementById('storeMinOrder').value||0)});ownerNotice(portalText('Store settings saved.','تنظیمات رستورانت ذخیره شد.'));await loadOwnerDashboard()}catch(e){ownerNotice(e.message,true)}}

const AERider={rider:null,assignments:[],performance:null,lastMile:null,refreshTimer:null,deadlineTimer:null};
window.showRiderPanel=function(id,button){document.querySelectorAll('.rider-panel').forEach(panel=>panel.classList.toggle('hidden',panel.id!==id));document.querySelectorAll('.rider-tab').forEach(tab=>tab.classList.toggle('active',tab===button));document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'})}
function riderStatusLabel(status){const labels={assigned:['Assigned','تخصیص‌شده'],accepted:['Accepted','پذیرفته‌شده'],at_restaurant:['At restaurant','در رستورانت'],picked_up:['Picked up','دریافت‌شده'],on_the_way:['On the way','در راه'],delivered:['Delivered','تحویل‌شده'],cancelled:['Cancelled','لغوشده']},value=labels[status]||[String(status||'').replaceAll('_',' '),String(status||'').replaceAll('_',' ')];return portalText(value[0],value[1])}
function riderNotice(message,error=false){const el=document.getElementById('riderToast');if(!el)return;el.className=`notice ${error?'error':'success'}`;el.textContent=message;clearTimeout(riderNotice.timer);riderNotice.timer=setTimeout(()=>el.classList.add('hidden'),5000)}
function riderPhone(value){const phone=String(value||'').replace(/[^0-9+]/g,'');return phone?`<a class="rider-contact-link" href="tel:${portalEsc(phone)}">☎ ${portalEsc(value)}</a>`:''}
function riderMapLink(label,address,latitude=null,longitude=null){const destination=latitude!=null&&longitude!=null?`${latitude},${longitude}`:address;if(!destination)return'';return`<a class="btn btn-light btn-sm" target="_blank" rel="noopener" href="https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(destination)}">${portalEsc(label)}</a>`}
function riderTimeline(status){const steps=[['accepted','Accept','پذیرش'],['at_restaurant','Arrive','رسیدن'],['picked_up','Pick up','دریافت'],['on_the_way','Deliver','حرکت'],['delivered','Complete','تکمیل']],order={assigned:0,accepted:1,at_restaurant:2,picked_up:3,on_the_way:4,delivered:5,cancelled:-1},index=order[status]??0;return`<ol class="rider-stepper">${steps.map(([key,en,fa],i)=>`<li class="${i<index?'done':i===index?'current':''}"><span>${i<index?'✓':i+1}</span><small>${portalEsc(portalText(en,fa))}</small></li>`).join('')}</ol>`}
function riderNext(a){const nextByStatus={assigned:'accepted',accepted:'at_restaurant',at_restaurant:'picked_up',picked_up:'on_the_way',on_the_way:'delivered'},labels={accepted:['Accept delivery','پذیرش ارسال'],at_restaurant:['I arrived at the restaurant','به رستورانت رسیدم'],picked_up:['I collected the order','سفارش را گرفتم'],on_the_way:['Start delivery','حرکت به‌سوی مشتری'],delivered:['Confirm delivered','تأیید تحویل']},next=nextByStatus[a.status];if(!next)return'';const proof=AERider.lastMile?.active,needsPin=next==='delivered'&&proof?.pinEnabled&&!proof?.pinVerified;return`<button class="btn btn-primary delivery-next" type="button" ${needsPin?'disabled aria-disabled="true"':''} onclick="riderAssignmentStatus('${portalEsc(a.id)}','${next}')">${portalEsc(portalText(...labels[next]))}</button>${needsPin?`<p class="rider-action-note">${portalEsc(portalText('Verify the customer code before completing this delivery.','پیش از تکمیل ارسال، کد مشتری را تأیید کنید.'))}</p>`:''}`}
function riderPinPanel(a){const proof=AERider.lastMile?.active;if(!proof||String(proof.assignmentId)!==String(a.id)||!proof.pinEnabled)return'';if(proof.pinVerified)return`<div class="rider-pin verified"><span aria-hidden="true">✓</span><div><b>${portalEsc(portalText('Customer code verified','کد مشتری تأیید شد'))}</b><small>${portalEsc(portalText('You can now confirm the handoff.','اکنون می‌توانید تحویل را تأیید کنید.'))}</small></div></div>`;if(a.status!=='on_the_way')return`<div class="rider-pin"><span aria-hidden="true">🔐</span><div><b>${portalEsc(portalText('Delivery code required at handoff','هنگام تحویل کد لازم است'))}</b><small>${portalEsc(portalText('Ask for the code only after reaching the customer.','فقط پس از رسیدن به مشتری کد را بخواهید.'))}</small></div></div>`;return`<form class="rider-pin rider-pin-form" onsubmit="verifyRiderPin(event,'${portalEsc(a.id)}')"><div><b>${portalEsc(portalText('Enter customer code','کد مشتری را وارد کنید'))}</b><small>${portalEsc(portalText('Four digits shown to the customer.','کد چهاررقمی نمایش‌داده‌شده به مشتری.'))}</small></div><input name="pin" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{4}" minlength="4" maxlength="4" required aria-label="Four-digit delivery code"><button class="btn btn-dark btn-sm" type="submit">${portalEsc(portalText('Verify','تأیید'))}</button></form>`}
function renderActiveDelivery(a){const proof=AERider.lastMile?.active,customerLocation=proof&&String(proof.assignmentId)===String(a.id)?proof.location:null,eta=proof?.roughEtaMinutes!=null?`<span>⏱ ${portalEsc(proof.roughEtaMinutes)} ${portalEsc(portalText('min estimate','دقیقه تخمینی'))}</span>`:'',deadline=a.accept_by&&a.status==='assigned'?`<span>⌛ ${portalEsc(portalText('Accept before','پذیرش تا'))} ${new Date(a.accept_by).toLocaleTimeString()}</span>`:'';return`<article class="delivery-card rider-job-card"><div class="delivery-head"><div><span class="rider-order-label">${portalEsc(portalText('Order','سفارش'))}</span><h3>${portalEsc(a.order_number)}</h3><div class="muted">${portalEsc(a.restaurant_name||'')}</div></div><span class="status-badge status-${portalEsc(a.status)}">${portalEsc(riderStatusLabel(a.status))}</span></div>${riderTimeline(a.status)}<div class="rider-job-meta"><span>${portalMoney(a.total)}</span>${eta}${deadline}</div>${portalItems(a.items)?`<div class="rider-order-items"><b>${portalEsc(portalText('Order items','اقلام سفارش'))}</b><p>${portalItems(a.items)}</p></div>`:''}<div class="rider-route-grid"><section><span class="rider-stop-number">1</span><div><small>${portalEsc(portalText('PICK UP','دریافت'))}</small><b>${portalEsc(a.restaurant_name||'')}</b><p>${portalEsc(a.restaurant_address||'')}</p><div class="portal-actions">${riderPhone(a.restaurant_phone)}${riderMapLink(portalText('Directions','مسیریابی'),a.restaurant_address)}</div></div></section><section><span class="rider-stop-number">2</span><div><small>${portalEsc(portalText('DELIVER','تحویل'))}</small><b>${portalEsc(portalText('Customer','مشتری'))}</b><p>${portalEsc(a.delivery_address||'')}</p><div class="portal-actions">${riderPhone(a.delivery_phone)}${riderMapLink(portalText('Directions','مسیریابی'),a.delivery_address,customerLocation?.latitude,customerLocation?.longitude)}</div></div></section></div>${a.order_notes?`<div class="rider-note"><b>${portalEsc(portalText('Delivery note','یادداشت ارسال'))}</b><p>${portalEsc(a.order_notes)}</p></div>`:''}${riderPinPanel(a)}${riderNext(a)}</article>`}
function renderHistoryDelivery(a){const time=a.delivered_at||a.updated_at||a.assigned_at;return`<article class="delivery-card rider-history-card"><div class="delivery-head"><div><b>${portalEsc(a.order_number)}</b><div>${portalEsc(a.restaurant_name||'')}</div></div><span class="status-badge status-${portalEsc(a.status)}">${portalEsc(riderStatusLabel(a.status))}</span></div><div class="portal-meta"><span>${time?new Date(time).toLocaleString():'—'}</span><span>${portalMoney(a.total)}</span></div></article>`}
window.renderRiderHistory=function(){const el=document.getElementById('riderPast');if(!el)return;const filter=document.getElementById('riderHistoryFilter')?.value||'all',past=AERider.assignments.filter(a=>['delivered','cancelled'].includes(a.status)&& (filter==='all'||a.status===filter));el.innerHTML=past.length?past.slice(0,50).map(renderHistoryDelivery).join(''):`<div class="portal-empty">${portalEsc(portalText('No deliveries match this filter.','سفارشی مطابق این فیلتر نیست.'))}</div>`}
function renderRiderPerformance(){const p=AERider.performance||{},r=AERider.rider||{},el=document.getElementById('riderPerformance'),profile=document.getElementById('riderServiceProfile');if(el)el.innerHTML=[[portalText('All deliveries','تمام ارسال‌ها'),p.deliveries??r.total_deliveries??0],[portalText('Last 30 days','۳۰ روز اخیر'),p.deliveries30d??0],[portalText('Average acceptance','میانگین پذیرش'),p.avgAcceptMinutes==null?'—':`${p.avgAcceptMinutes} min`],[portalText('Average delivery','میانگین ارسال'),p.avgDeliveryMinutes==null?'—':`${p.avgDeliveryMinutes} min`]].map(([label,value])=>`<div><small>${portalEsc(label)}</small><strong>${portalEsc(value)}</strong></div>`).join('');if(profile)profile.innerHTML=[[portalText('Vehicle','وسیله'),r.vehicle||'—'],[portalText('Service area','ساحه کاری'),r.service_area||'—'],[portalText('Account status','وضعیت حساب'),r.status||'—'],[portalText('Cash held for settlement','پول نقد برای تسویه'),portalMoney(r.cash_balance||0)]].map(([label,value])=>`<div><small>${portalEsc(label)}</small><b>${portalEsc(value)}</b></div>`).join('')}
function updateRiderDeadline(){const el=document.getElementById('riderDeadline'),a=AERider.assignments.find(item=>!['delivered','cancelled'].includes(item.status));if(!el||!a?.accept_by||a.status!=='assigned'){el?.classList.add('hidden');return}const seconds=Math.max(0,Math.floor((new Date(a.accept_by).getTime()-Date.now())/1000));el.className=`rider-deadline ${seconds<60?'urgent':''}`;el.textContent=seconds?`${portalText('Accept in','پذیرش تا')} ${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`:portalText('Acceptance time ended','زمان پذیرش پایان یافت')}
function showRiderDashboard(){document.getElementById('riderAuth')?.classList.add('hidden');document.getElementById('riderDashboard')?.classList.remove('hidden');loadRiderDashboard();if(AERider.refreshTimer)clearInterval(AERider.refreshTimer);AERider.refreshTimer=setInterval(()=>{if(document.visibilityState==='visible')loadRiderDashboard()},30000);if(AERider.deadlineTimer)clearInterval(AERider.deadlineTimer);AERider.deadlineTimer=setInterval(updateRiderDeadline,1000)}
async function loadRiderDashboard(){const err=document.getElementById('riderPortalError');try{const[dashResult,slaResult,lastMileResult]=await Promise.allSettled([portalQuery('portal.riderDashboard'),portalQuery('dispatch.riderSla'),portalQuery('lastmile.riderContext')]);if(dashResult.status!=='fulfilled')throw dashResult.reason;const d=dashResult.value,r=d.rider||{};AERider.rider=r;AERider.assignments=d.assignments||[];AERider.performance=slaResult.status==='fulfilled'?slaResult.value.performance:null;AERider.lastMile=lastMileResult.status==='fulfilled'?lastMileResult.value:null;if(err)err.classList.add('hidden');document.getElementById('riderName').textContent=r.full_name||portalText('Rider','پیک');const active=AERider.assignments.filter(a=>!['delivered','cancelled'].includes(a.status)),todayStart=new Date();todayStart.setHours(0,0,0,0);const today=AERider.assignments.filter(a=>a.status==='delivered'&&new Date(a.delivered_at||a.updated_at||0)>=todayStart).length;document.getElementById('riderStats').innerHTML=[[portalText('Delivered today','تحویل امروز'),today],[portalText('Last 30 days','۳۰ روز اخیر'),AERider.performance?.deliveries30d??0],[portalText('Shift','شیفت'),active.length?portalText('On a delivery','در حال ارسال'):r.is_available?portalText('Available','آماده'):portalText('Offline','غیرفعال')],[portalText('Cash held','پول نقد'),portalMoney(r.cash_balance||0)]].map(([label,value])=>`<div class="portal-stat"><small>${portalEsc(label)}</small><strong>${portalEsc(value)}</strong></div>`).join('');const availability=document.getElementById('riderAvailable');availability.checked=!!r.is_available;availability.disabled=active.length>0;const shiftDot=document.getElementById('riderShiftDot'),shiftLabel=document.getElementById('riderShiftLabel');shiftDot?.classList.toggle('live',!!r.is_available||active.length>0);if(shiftLabel)shiftLabel.textContent=active.length?portalText('Delivery in progress','ارسال در حال انجام'):r.is_available?portalText('Ready for assignments','آماده دریافت سفارش'):portalText('Shift offline','شیفت غیرفعال');document.getElementById('riderActive').innerHTML=active.length?active.map(renderActiveDelivery).join(''):`<div class="rider-empty-job"><span aria-hidden="true">✓</span><h3>${portalEsc(portalText('No active delivery','ارسال فعالی نیست'))}</h3><p>${portalEsc(r.is_available?portalText('You are available. New assignments will appear here.','شما آماده هستید. سفارش جدید در اینجا نمایش داده می‌شود.'):portalText('Turn on availability when you are ready for a new assignment.','وقتی آماده سفارش جدید هستید، وضعیت آماده‌باش را فعال کنید.'))}</p></div>`;renderRiderHistory();renderRiderPerformance();updateRiderDeadline()}catch(e){if(err){err.className='notice error';err.textContent=e.message}}}
window.setRiderAvailability=async function(){const input=document.getElementById('riderAvailable'),available=input.checked;input.disabled=true;try{await portalMutation('portal.riderSetAvailability',{available});if(!available)stopRiderLocation();riderNotice(available?portalText('You are available for assignments.','برای دریافت سفارش آماده هستید.'):portalText('Your shift is offline.','شیفت شما غیرفعال شد.'));await loadRiderDashboard()}catch(e){input.checked=!available;riderNotice(e.message,true)}finally{input.disabled=false}}
window.riderAssignmentStatus=async function(assignmentId,status){if(status==='delivered'&&!confirm(portalText('Confirm that the order has reached the customer?','تأیید می‌کنید که سفارش به مشتری رسیده است؟')))return;const button=document.activeElement;if(button instanceof HTMLButtonElement)button.disabled=true;try{await portalMutation('portal.riderUpdateAssignment',{assignmentId,status});if(status==='delivered')stopRiderLocation();riderNotice(portalText('Delivery status updated.','وضعیت ارسال به‌روزرسانی شد.'));await loadRiderDashboard()}catch(e){riderNotice(e.message,true)}finally{if(button instanceof HTMLButtonElement)button.disabled=false}}
window.verifyRiderPin=async function(event,assignmentId){event.preventDefault();const form=event.currentTarget,pin=String(new FormData(form).get('pin')||'');portalSetBusy(form,true,portalText('Checking…','در حال بررسی…'));try{await portalMutation('lastmile.riderVerifyPin',{assignmentId,pin});riderNotice(portalText('Customer code verified.','کد مشتری تأیید شد.'));await loadRiderDashboard()}catch(e){riderNotice(e.message,true)}finally{portalSetBusy(form,false)}}
window.startRiderLocation=function(){const out=document.getElementById('gpsStatus'),dot=document.getElementById('gpsDot'),stamp=document.getElementById('riderLocationStamp'),active=AERider.assignments.some(a=>!['delivered','cancelled'].includes(a.status));if(!active){riderNotice(portalText('Location can be shared only during an active delivery.','موقعیت فقط هنگام ارسال فعال شریک می‌شود.'),true);return}if(!navigator.geolocation){out.textContent=portalText('Location is not supported on this device.','این دستگاه موقعیت‌یابی را پشتیبانی نمی‌کند.');return}if(AEPortal.geoWatch!=null)return;out.textContent=portalText('Requesting location permission…','درخواست اجازه موقعیت…');AEPortal.geoWatch=navigator.geolocation.watchPosition(async pos=>{const now=Date.now();if(now-AEPortal.lastGeoSent<15000)return;AEPortal.lastGeoSent=now;try{await portalMutation('portal.riderUpdateLocation',{latitude:pos.coords.latitude,longitude:pos.coords.longitude});dot?.classList.add('live');out.textContent=portalText('Live location is on','موقعیت زنده فعال است');if(stamp)stamp.textContent=`${portalText('Last shared','آخرین اشتراک')}: ${new Date().toLocaleTimeString()} · ±${Math.round(pos.coords.accuracy)}m`}catch(e){out.textContent=e.message}},geoError=>{dot?.classList.remove('live');out.textContent=geoError.message},{enableHighAccuracy:true,maximumAge:10000,timeout:20000})}
window.stopRiderLocation=function(){if(AEPortal.geoWatch!=null&&navigator.geolocation){navigator.geolocation.clearWatch(AEPortal.geoWatch);AEPortal.geoWatch=null}document.getElementById('gpsDot')?.classList.remove('live');const out=document.getElementById('gpsStatus'),stamp=document.getElementById('riderLocationStamp');if(out)out.textContent=portalText('Location sharing is off.','اشتراک موقعیت خاموش است.');if(stamp)stamp.textContent=''}

async function portalAdminLoad(){if(typeof opsQuery!=='function'||typeof AEOPS==='undefined'||!AEOPS.token)return;try{const[accounts,partners,riders]=await Promise.all([opsQuery('portal.adminAccounts',null,true),opsQuery('operations.adminPartnerApplications',{limit:100},true),opsQuery('operations.adminRiderApplications',{limit:100},true)]);renderPortalAccess(accounts||[],partners||[],riders||[])}catch(e){const el=document.getElementById('portalAccessError');if(el){el.className='notice error';el.textContent=e.message}}}
window.loadPortalAdmin=portalAdminLoad;
function normalizedPortalUser(phone){return String(phone||'').replace(/[^0-9+]/g,'').toLowerCase()}
function renderPortalAccess(accounts,partners,riders){const el=document.getElementById('portalAccess');if(!el)return;const approvedPartners=partners.filter(x=>x.status==='approved'),approvedRiders=riders.filter(x=>x.status==='approved');const accountRows=accounts.map(a=>`<div class="access-row"><div><b>${portalEsc(a.role==='owner'?(a.restaurant_name||'Restaurant owner'):(a.rider_name||'Rider'))}</b><div>${portalEsc(a.username)} · ${portalEsc(a.role)}</div><small>${a.activated_at?'Activated':'Not activated'}${a.last_login_at?` · last login ${new Date(a.last_login_at).toLocaleString()}`:''}</small></div><div class="portal-actions"><span class="status-badge ${a.active?'status-approved':'status-inactive'}">${a.active?'active':'inactive'}</span><button class="btn btn-light btn-sm" onclick="setPortalAccount('${portalEsc(a.id)}',${!a.active})">${a.active?'Disable':'Enable'}</button></div></div>`).join('');const candidates=[...approvedPartners.map(x=>({type:'partner',id:x.id,name:x.restaurant_name,phone:x.phone,role:'owner'})),...approvedRiders.map(x=>({type:'rider',id:x.id,name:x.full_name,phone:x.phone,role:'rider'}))].filter(c=>!accounts.some(a=>a.role===c.role&&a.username===normalizedPortalUser(c.phone)));el.innerHTML=`<div class="access-grid"><div class="portal-card"><h3>Ready for portal access</h3><div class="portal-list">${candidates.length?candidates.map(c=>`<div class="access-row"><div><b>${portalEsc(c.name)}</b><div>${portalEsc(c.phone)} · ${portalEsc(c.role)}</div></div><button class="btn btn-primary btn-sm" onclick="createPortalInvite('${c.type}','${portalEsc(c.id)}')">Create invite</button></div>`).join(''):'<div class="portal-empty">No approved applicants waiting for access.</div>'}</div></div><div class="portal-card"><h3>Portal accounts</h3><div class="portal-list">${accountRows||'<div class="portal-empty">No portal accounts yet.</div>'}</div></div></div>`}
window.createPortalInvite=async function(type,applicationId){try{const d=await opsMutation('portal.adminCreateInvite',{type,applicationId},true);if(!/^[a-f0-9]{64}$/i.test(String(d.activationToken||'')))throw new Error('Afghan Eats could not create a valid activation invitation. Please retry.');const url=`${location.origin}/activate.html?token=${encodeURIComponent(d.activationToken)}`,box=document.getElementById('portalInviteOutput');box.className='invite-box';box.innerHTML=`<b>One-time ${portalEsc(d.role)} activation link</b><p>Username: <b>${portalEsc(d.username)}</b> · expires in ${portalEsc(d.expiresInHours)} hours.</p><textarea id="portalInviteLink" readonly>${portalEsc(url)}</textarea><button class="btn btn-dark btn-sm" onclick="copyPortalInvite()">Copy activation link</button><p class="muted">Send this link privately to the approved partner/rider. Do not post it publicly.</p>`;await portalAdminLoad()}catch(e){alert(e.message)}}
window.copyPortalInvite=async function(){const v=document.getElementById('portalInviteLink')?.value||'';try{await navigator.clipboard.writeText(v);alert('Activation link copied.')}catch{}}
window.setPortalAccount=async function(id,active){try{await opsMutation('portal.adminSetAccountActive',{id,active},true);await portalAdminLoad()}catch(e){alert(e.message)}}

async function loadLiveDelivery(){const box=document.getElementById('liveDelivery');if(!box)return;const id=new URLSearchParams(location.search).get('id'),phone=document.getElementById('trackPhone')?.value.trim()||JSON.parse(localStorage.getItem('ae_last_order')||'null')?.customerPhone||'';if(!id||phone.length<9)return;try{const d=await portalQuery('portal.liveTracking',{orderId:id,phone},false);if(!d.delivery){box.innerHTML=`<div class="live-delivery"><b>🛵 ${portalText('Finding a rider','در حال یافتن پیک')}</b><p class="muted">${portalText('Your order is in the restaurant workflow. Rider details will appear after assignment.','سفارش در روند رستورانت است. معلومات پیک پس از تخصیص نمایش داده می‌شود.')}</p></div>`;return}const x=d.delivery,hasLoc=x.last_latitude!=null&&x.last_longitude!=null,loc=hasLoc?`https://www.openstreetmap.org/?mlat=${encodeURIComponent(x.last_latitude)}&mlon=${encodeURIComponent(x.last_longitude)}#map=16/${encodeURIComponent(x.last_latitude)}/${encodeURIComponent(x.last_longitude)}`:'';box.innerHTML=`<div class="live-delivery"><div class="live-rider"><div class="rider-avatar">🛵</div><div><b>${portalEsc(x.rider_name)}</b><div class="muted">${portalEsc(x.vehicle||'rider')} · ${portalEsc(x.delivery_status)}</div></div>${hasLoc?`<a class="btn btn-light btn-sm" target="_blank" rel="noopener" href="${loc}">${portalText('View live location','مشاهده موقعیت')}</a>`:''}</div>${hasLoc?`<div class="live-location">📍 ${portalText('Location updated','موقعیت به‌روزرسانی شده')}: ${x.location_updated_at?new Date(x.location_updated_at).toLocaleTimeString():'—'}</div>`:`<div class="live-location muted">${portalText('The rider has not shared a live GPS point yet.','پیک هنوز موقعیت زنده GPS را شریک نکرده است.')}</div>`}</div>`;if(['delivered','cancelled'].includes(d.status)&&AEPortal.liveTimer){clearInterval(AEPortal.liveTimer);AEPortal.liveTimer=null}}catch(e){box.innerHTML=`<div class="notice error">${portalEsc(e.message)}</div>`}}
window.trackOrderWithLiveRider=async function(){if(typeof secureTrackOrder==='function')await secureTrackOrder();await loadLiveDelivery();if(AEPortal.liveTimer)clearInterval(AEPortal.liveTimer);AEPortal.liveTimer=setInterval(loadLiveDelivery,20000)}

function bindOwnerForm(id,handler){const form=document.getElementById(id);if(!form||form.dataset.ownerBound)return;form.addEventListener('submit',handler);form.dataset.ownerBound='1'}
async function initOwnerPortal(){if(!document.getElementById('ownerDashboard'))return;bindOwnerForm('ownerItemForm',window.saveOwnerMenuItem);bindOwnerForm('ownerCategoryForm',window.saveOwnerCategory);bindOwnerForm('ownerProfileForm',window.saveOwnerProfile);const u=new URLSearchParams(location.search).get('username');if(u)document.querySelector('#ownerAuth input[name=username]').value=u;if(await portalVerify('owner'))showOwnerDashboard()}
async function initRiderPortal(){if(!document.getElementById('riderDashboard'))return;const u=new URLSearchParams(location.search).get('username');if(u)document.querySelector('#riderAuth input[name=username]').value=u;if(await portalVerify('rider'))showRiderDashboard()}
document.addEventListener('DOMContentLoaded',()=>{initOwnerPortal();initRiderPortal();if(document.getElementById('portalAccess')&&typeof verifyAdminSession==='function')setTimeout(portalAdminLoad,700)});
